1	import { DBSchema, openDB } from 'idb';
2	import { useFeatureFlagEnabled } from 'posthog-js/react';
3	import {
4	  createContext,
5	  Dispatch,
6	  ReactNode,
7	  useContext,
8	  useEffect,
9	  useReducer,
10	  useState,
11	} from 'react';
12	
13	// Define the shape of your feature flags
14	type FlagValue = {
15	  location: 'unset' | 'local' | 'remote';
16	  value: boolean;
17	};
18	
19	interface FeatureFlags {
20	  'edit-line-items': FlagValue;
21	  'assignments-add-all': FlagValue;
22	  'receipt-desktop-table': FlagValue;
23	}
24	
25	// Define actions
26	interface SetFlagAction {
27	  type: 'SET_FLAG';
28	  value: FlagValue;
29	  name: keyof FeatureFlags;
30	}
31	
32	interface SetFlagsAction {
33	  type: 'SET_FLAGS';
34	  flags: FeatureFlags;
35	}
36	
37	interface ClearFlagsAction {
38	  type: 'CLEAR_FLAGS';
39	}
40	
41	type FeatureFlagAction = SetFlagAction | SetFlagsAction | ClearFlagsAction;
42	
43	// IndexedDB helpers
44	const DB_NAME = 'feature-flag-store';
45	const STORE_NAME = 'flags';
46	
47	interface FeatureFlagDB extends DBSchema {
48	  flags: {
49	    key: string;
50	    value: {
51	      name: string;
52	      value: FlagValue;
53	    };
54	  };
55	}
56	
57	const createFeatureFlagDB = async () => {
58	  openDB<FeatureFlagDB>(DB_NAME, 1, {
59	    upgrade(db) {
60	      db.createObjectStore(STORE_NAME);
61	    },
62	  });
63	};
64	
65	async function getFlagsFromDB(): Promise<FeatureFlags> {
66	  const db = await openDB<FeatureFlagDB>(DB_NAME);
67	
68	  const flags = await db.getAll(STORE_NAME);
69	
70	  return flags.reduce((acc, flag) => {
71	    acc[flag.name as keyof FeatureFlags] = flag.value;
72	    return acc;
73	  }, {} as FeatureFlags);
74	}
75	
76	async function setFlagInDB(flag: string, value: FlagValue) {
77	  const db = await openDB<FeatureFlagDB>(DB_NAME);
78	  await db.put(STORE_NAME, { name: flag, value }, flag);
79	}
80	
81	async function clearFlagsFromDB() {
82	  const db = await openDB<FeatureFlagDB>(DB_NAME);
83	  await db.clear(STORE_NAME);
84	}
85	
86	// Initial state
87	const initialFlags: FeatureFlags = {
88	  'edit-line-items': { location: 'unset', value: false },
89	  'assignments-add-all': { location: 'unset', value: false },
90	  'receipt-desktop-table': { location: 'unset', value: false },
91	};
92	
93	// Reducer
94	function featureFlagReducer(
95	  state: FeatureFlags,
96	  action: FeatureFlagAction
97	): FeatureFlags {
98	  switch (action.type) {
99	    case 'SET_FLAGS':
100	      return action.flags;
101	
102	    case 'SET_FLAG':
103	      setFlagInDB(action.name, action.value);
104	
105	      return {
106	        ...state,
107	        [action.name]: action.value,
108	      };
109	
110	    case 'CLEAR_FLAGS':
111	      clearFlagsFromDB();
112	      return initialFlags;
113	
114	    default:
115	      return state;
116	  }
117	}
118	
119	// Contexts
120	export const FeatureFlagStateContext = createContext<{
121	  featureFlags: FeatureFlags;
122	  isOverridden: boolean;
123	}>({ featureFlags: initialFlags, isOverridden: false });
124	const FeatureFlagDispatchContext = createContext<
125	  Dispatch<FeatureFlagAction> | undefined
126	>(undefined);
127	
128	// Provider
129	export const FeatureFlagProvider = ({ children }: { children: ReactNode }) => {
130	  const [isDBCreated, setIsDBCreated] = useState(false);
131	  const [state, dispatch] = useReducer(featureFlagReducer, initialFlags);
132	
133	  useEffect(() => {
134	    createFeatureFlagDB().then(() => {
135	      setIsDBCreated(true);
136	    });
137	  }, []);
138	
139	  useEffect(() => {
140	    const fetchFlags = async () => {
141	      const flags = await getFlagsFromDB();
142	      dispatch({ type: 'SET_FLAGS', flags });
143	    };
144	
145	    if (isDBCreated) {
146	      fetchFlags();
147	    }
148	  }, [isDBCreated]);
149	
150	  return (
151	    <FeatureFlagStateContext.Provider
152	      value={{
153	        featureFlags: state,
154	        isOverridden: Object.values(state).some(
155	          (flag) => flag.location !== 'unset'
156	        ),
157	      }}
158	    >
159	      <FeatureFlagDispatchContext.Provider value={dispatch}>
160	        {children}
161	      </FeatureFlagDispatchContext.Provider>
162	    </FeatureFlagStateContext.Provider>
163	  );
164	};
165	
166	// Hooks for consuming context
167	
168	export function useFeatureFlag(flag: keyof FeatureFlags) {
169	  const { featureFlags } = useContext(FeatureFlagStateContext);
170	  const specificFeatureRemoteValue = useFeatureFlagEnabled(flag);
171	
172	  if (!featureFlags[flag] || featureFlags[flag].location === 'unset') {
173	    return specificFeatureRemoteValue;
174	  }
175	
176	  return featureFlags[flag].location === 'local'
177	    ? featureFlags[flag].value
178	    : specificFeatureRemoteValue;
179	}
