1	import { useEffect, useState } from 'react';
2	
3	/**
4	 * A hook to detect if the user is on a mobile device based on screen width.
5	 *
6	 * This hook listens for changes in screen size and returns `true` if the
7	 * screen width is less than the mobile breakpoint (768px).
8	 *
9	 * @returns {boolean} `true` if the screen width is less than the mobile breakpoint, otherwise `false`.
10	 *
11	 * @example
12	 * ```tsx
13	 * import { useMobile } from './useMobile';
14	 *
15	 * function MyComponent() {
16	 *   const isMobile = useMobile();
17	 *
18	 *   return (
19	 *     <div>
20	 *       {isMobile ? <p>Mobile view</p> : <p>Desktop view</p>}
21	 *     </div>
22	 *   );
23	 * }
24	 * ```
25	 */
26	export function useMobile(): boolean {
27	  const [isMobile, setIsMobile] = useState<boolean>(false);
28	
29	  useEffect(() => {
30	    // Check if window is defined (browser environment)
31	    if (typeof window !== 'undefined') {
32	      const mql = window.matchMedia('(max-width: 767px)');
33	      const onChange = (e: MediaQueryListEvent) => {
34	        setIsMobile(e.matches);
35	      };
36	      mql.addEventListener('change', onChange);
37	      setIsMobile(mql.matches);
