import { Trans, useLingui } from '@lingui/react/macro';
import { LazyMotion, domAnimation, m } from 'framer-motion';
import { ChevronDown } from 'lucide-react';
import { useState } from 'react';

import NumericInput from '@/components/NumericInput';
import {
  formatCurrency,
  truncateToTwoDecimals,
} from '@/components/Receipt/utils/format-currency';
import { Input } from '@/components/ui/input';
import { Toggle } from '@/components/ui/toggle';
import type { ReceiptLineItem } from '@/models/ReceiptLineItem';

export default function LineItemForm({
  item,
  receiptId,
  onNameChange,
  onQuantityChange,
  mutate,
  onEditCancel,
}: {
  item: ReceiptLineItem;
  receiptId: string;
  onNameChange: (name: string) => void;
  onQuantityChange: (quantity: number) => void;
  mutate: (data: {
    receiptId: string;
    itemId: string;
    name?: string;
    quantity?: number;
    price_per_item?: number;
  }) => void;
  onEditCancel?: () => void;
}) {
  const [formName, setFormName] = useState(item.name ?? '');
  const [formQuantity, setFormQuantity] = useState<number>(
    item.quantity.toNumber()
  );
  const [formPricePerItem, setFormPricePerItem] = useState<string>(
    truncateToTwoDecimals(item.pricePerItem)
  );
  const [isNameFocused, setIsNameFocused] = useState(false);
  const { t } = useLingui();

  const formTotal = Number(formQuantity) * (parseFloat(formPricePerItem) || 0);

  // Persist name change with debounce
  const handleNameChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setFormName(e.target.value);
    onNameChange(e.target.value);
  };

  // Handle quantity change from NumericInput (both input and buttons)
  const handleNumericQuantityChange = (newQuantity: number) => {
    setFormQuantity(newQuantity);
    onQuantityChange(newQuantity);
  };

  // For price, only persist after truncation (onBlur)
  const handlePriceChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setFormPricePerItem(e.target.value);
  };

  const handlePriceBlur = () => {
    const num = parseFloat(formPricePerItem);
    const originalTruncated =
      Math.trunc(item.pricePerItem.toNumber() * 100) / 100;
    if (!isNaN(num)) {
      const truncated = Math.trunc(num * 100) / 100;
      const truncatedStr = truncateToTwoDecimals(truncated);
      setFormPricePerItem(truncatedStr);
      if (truncated !== originalTruncated) {
        mutate({
          receiptId,
          itemId: item.id,
          price_per_item: truncated,
        });
      }
    } else {
      setFormPricePerItem('0.00');
      if (originalTruncated !== 0) {
        mutate({
          receiptId,
          itemId: item.id,
          price_per_item: 0,
        });
      }
    }
  };

  // Persist price per item when Enter is pressed
  const handlePriceKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter') {
      handlePriceBlur();
    }
  };

  return (
    <LazyMotion features={domAnimation}>
    <div className="flex flex-col gap-3 bg-background p-2">
      <div className="flex items-center justify-between gap-2 border-b border-border/40 pb-2">
        <m.div
          className="flex-1"
          layout
          transition={{
            type: 'spring',
            stiffness: 300,
            damping: 30,
            layout: {
              type: 'spring',
              stiffness: 300,
              damping: 30,
            },
          }}
        >
          <label htmlFor={`item-name-${item.id}`} className="sr-only">
            <Trans>Item name</Trans>
          </label>
          <Input
            id={`item-name-${item.id}`}
            value={formName}
            onChange={handleNameChange}
            onFocus={() => setIsNameFocused(true)}
            onBlur={() => setIsNameFocused(false)}
            placeholder={t`Item name`}
            required
          />
        </m.div>

        {!isNameFocused && (
          <m.span
            key="formTotal"
            layout
            initial={{ opacity: 0, scale: 0.8 }}
            animate={{ opacity: 1, scale: 1 }}
            transition={{
              type: 'spring',
              stiffness: 300,
              damping: 30,
              layout: {
                type: 'spring',
                stiffness: 300,
                damping: 30,
              },
            }}
            className="whitespace-nowrap text-right font-semibold"
          >
            {formatCurrency(formTotal)}
          </m.span>
        )}

        {onEditCancel && (
          <Toggle pressed onClick={onEditCancel}>
            <ChevronDown />
          </Toggle>
        )}
      </div>

      <div className="flex flex-col gap-2">
        <label
          htmlFor={`item-quantity-${item.id}`}
          className="text-sm font-medium"
        >
          <Trans>Quantity</Trans>
        </label>
        <NumericInput
          id={`item-quantity-${item.id}`}
          value={formQuantity}
          onChange={handleNumericQuantityChange}
          min={1}
          placeholder={t`Quantity`}
        />
      </div>

      <div className="flex flex-col gap-2">
        <label
          htmlFor={`item-price-${item.id}`}
          className="text-sm font-medium"
        >
          <Trans>Unit Price</Trans>
        </label>
        <div className="flex items-center gap-2">
          <span className="select-none pl-2 pr-1 text-lg text-muted-foreground">
            $
          </span>
          <Input
            id={`item-price-${item.id}`}
            type="number"
            value={formPricePerItem}
            onChange={handlePriceChange}
            onBlur={handlePriceBlur}
            onKeyDown={handlePriceKeyDown}
            placeholder={t`Unit price`}
            min={0}
            step="0.01"
            required
            className="text-center"
          />
        </div>
      </div>
    </div>
    </LazyMotion>
  );
}

