                          addSuffix: true,
                        })
                      : t`Unknown`}
                  </div>
                </div>

                <div className="mt-2 flex justify-end gap-2">
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={() => handleViewReceipt(receipt.id)}
