                        : t`View receipt from Unknown Merchant`
                    }
                  >
                    <Eye className="mr-1 h-3.5 w-3.5" aria-hidden />
                    <Trans>View</Trans>
                  </Button>
                </div>
              </m.li>
            ))}
          </ul>
        )}
      </CardContent>
    </Card>
    </LazyMotion>
  );
};

export default ReceiptHistory;

