    setPendingImage(null);
    setProcessedImage(null);
    setCrop(undefined);
    setCompletedCrop(null);
    setImageDims(null);
    setEraseRects([]);
    navigate('/');
  }, [
    navigate,
    setPendingImage,
    setProcessedImage,
    setCrop,
    setCompletedCrop,
    setImageDims,
    setEraseRects,
  ]);

  const handlePreview = useCallback(async () => {
    if (!pendingImage || !localPreview) return;

