import { Trans, useLingui } from '@lingui/react/macro';
import { useAtom, useSetAtom } from 'jotai';
import { ArrowLeft, FileSearch, Loader2 } from 'lucide-react';
import { useCallback, useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';

import { Button } from '@/components/ui/button';
import {
  pendingImageAtom,
  processedImageAtom,
} from '@/features/image-prep/atoms/imagePrepAtoms';
import {
  completedCropAtom,
  cropAtom,
  eraseRectsAtom,
  imageDimsAtom,
} from '@/features/image-prep/atoms/imagePrepStateAtoms';
import { useReceiptAnalysisMutation } from '@/features/receipt-upload/hooks/useReceiptAnalysis';
import type { ReceiptAnalysisResult } from '@/features/receipt-upload/types';
import { useDocumentTitle } from '@/hooks/useDocumentTitle';

const PreviewPage = () => {
  const { t } = useLingui();
  const navigate = useNavigate();
  const [processedImage, setProcessedImage] = useAtom(processedImageAtom);
  const setPendingImage = useSetAtom(pendingImageAtom);
  const setCrop = useSetAtom(cropAtom);
  const setCompletedCrop = useSetAtom(completedCropAtom);
  const setImageDims = useSetAtom(imageDimsAtom);
  const setEraseRects = useSetAtom(eraseRectsAtom);
  const mutation = useReceiptAnalysisMutation();

  useDocumentTitle('Preview');

  // Guard: redirect on mount only if no processed image (handles direct URL access)
  useEffect(() => {
    if (!processedImage) {
      navigate('/prepare', { replace: true });
    }
  }, []);

  const [localPreview, setLocalPreview] = useState<string | null>(null);
  useEffect(() => {
    if (!processedImage) return;
    const url = URL.createObjectURL(processedImage);
    setLocalPreview(url);
    return () => {
      URL.revokeObjectURL(url);
      setLocalPreview(null);
    };
  }, [processedImage]);

  const handleBack = useCallback(() => {
    setProcessedImage(null);
    navigate('/prepare');
  }, [navigate, setProcessedImage]);

  const handleAnalyze = useCallback(() => {
    if (!processedImage) return;

    mutation.mutate(
      { file: processedImage },
      {
        onSuccess: (result: ReceiptAnalysisResult) => {
          if (result.success && result.is_receipt) {
            setProcessedImage(null);
            setPendingImage(null);
            setCrop(undefined);
            setCompletedCrop(null);
            setImageDims(null);
            setEraseRects([]);
            navigate(`/receipt/${result.receipt_data.id}`);
          }
        },
      }
    );
  }, [
    mutation,
    navigate,
    processedImage,
    setCrop,
    setCompletedCrop,
    setImageDims,
    setEraseRects,
    setPendingImage,
    setProcessedImage,
  ]);

  if (!processedImage || !localPreview) return null;

  const error = (() => {
    if (mutation.error) {
      return t`An error occurred while analyzing the document. Please try again.`;
    }
    if (mutation.data && !mutation.data.success) {
      return mutation.data.error || t`Failed to analyze document`;
    }
    if (mutation.data && mutation.data.success && !mutation.data.is_receipt) {
      const reason = mutation.data.receipt_data?.reason;
      return reason
        ? t`The image does not appear to be a receipt: ${reason}`
        : t`The uploaded image does not appear to be a payment document. Please upload a receipt, invoice, or bill.`;
    }
    return null;
  })();

  return (
    <div className="mx-auto flex max-w-md flex-col gap-4 px-4 pb-10 pt-6">
      {/* Header */}
      <div className="flex items-center gap-3">
        <Button
          variant="ghost"
          size="icon"
          onClick={handleBack}
          aria-label="Back to prepare"
          className="-ml-2 shrink-0"
          disabled={mutation.isPending}
        >
          <ArrowLeft className="size-5" />
        </Button>
        <div>
          <h1 className="font-display text-lg font-semibold leading-tight text-foreground">
            <Trans>Preview result</Trans>
          </h1>
          <p className="text-xs text-muted-foreground">
            <Trans>Verify edits look correct before analyzing</Trans>
          </p>
        </div>
      </div>

      {/* Processed image */}
      <div className="overflow-hidden rounded-lg border border-border">
        <img
          src={localPreview}
          alt="Processed receipt"
          className="block w-full object-contain"
        />
      </div>

      {/* Error */}
      {error && (
        <p
          role="alert"
          className="rounded-lg bg-destructive/10 px-4 py-3 text-sm text-destructive"
        >
          {error}
        </p>
      )}

      {/* Analyze button */}
      <Button
        type="button"
        size="lg"
        className="w-full"
        onClick={handleAnalyze}
        disabled={mutation.isPending}
      >
        {mutation.isPending ? (
          <>
            <Loader2 data-icon="inline-start" className="animate-spin" />
            <Trans>Analyzing…</Trans>
          </>
        ) : (
          <>
            <FileSearch data-icon="inline-start" />
            <Trans>Analyze receipt</Trans>
          </>
        )}
      </Button>
    </div>
  );
};

export default PreviewPage;

import { Trans, useLingui } from '@lingui/react/macro';
import { useAtomValue } from 'jotai';
import { Divide } from 'lucide-react';
import { useState } from 'react';

import NumericInput from '@/components/NumericInput';
import { formatCurrency } from '@/components/Receipt/utils/format-currency';
import { calculations } from '@/components/Receipt/utils/receipt-calculation';
import { CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Label } from '@/components/ui/label';
import {
  assignedUsersAtom,
  receiptAtom,
} from '@/features/receipt-collab/atoms/receiptAtoms';

export const EvenSplitTabCollab = () => {
  const { t } = useLingui();
  const assignedUsers = useAtomValue(assignedUsersAtom);
  const receiptUserIds = assignedUsers.map((a) => a.receiptUserId);
  const receipt = useAtomValue(receiptAtom);
  const defaultNumberOfPeople =
    receiptUserIds.length > 0 ? receiptUserIds.length : 1;
  const [numberOfPeople, setNumberOfPeople] = useState(defaultNumberOfPeople);

  // Reset the editable count when the number of assigned people changes,
  // adjusting state during render instead of in an effect.
  const [prevPeopleCount, setPrevPeopleCount] = useState(receiptUserIds.length);
  if (receiptUserIds.length !== prevPeopleCount) {
    setPrevPeopleCount(receiptUserIds.length);
    setNumberOfPeople(defaultNumberOfPeople);
  }

  if (!receipt) {
    return null;
  }

  const calculatedTotal = calculations.final.getReceiptTotal(receipt);
  const evenlySplitTotalRounded = calculatedTotal
    .div(numberOfPeople)
    .toDecimalPlaces(2);
  const hasEvenlySplitDifference = calculatedTotal
    .minus(evenlySplitTotalRounded.mul(numberOfPeople))
    .abs()
    .toDecimalPlaces(2)
    .gte(0.01);

  return (
    <>
      <CardHeader className="px-0">
        <CardTitle className="flex items-center text-xl font-bold">
          <div className="flex items-center gap-3">
            <Divide className="h-6 w-6" />
            <Trans>Split Evenly</Trans>
          </div>
        </CardTitle>
      </CardHeader>

      <CardContent className="p-0">
        <div className="flex flex-col gap-2">
          <Label htmlFor="number-of-people">
            <Trans>Split between how many people?</Trans>
          </Label>
          <NumericInput
            id="number-of-people"
            value={numberOfPeople}
            onChange={setNumberOfPeople}
            min={1}
            placeholder={t`Number of people`}
          />
          <div className="mt-2 flex flex-col gap-2 border-t-2 border-border pt-3">
            <div className="flex items-center justify-between">
              <span className="text-base font-semibold">
                <Trans>Per Person:</Trans>
              </span>
              <span className="text-xl font-bold">
                {formatCurrency(evenlySplitTotalRounded)}
              </span>
            </div>
            {hasEvenlySplitDifference && (
              <p className="rounded-md bg-muted/30 px-3 py-2 text-center text-sm text-muted-foreground">
                <Trans>
                  Note: One person will pay an additional{' '}
                  {formatCurrency(
                    Math.abs(
                      calculatedTotal
                        .minus(evenlySplitTotalRounded.mul(numberOfPeople))
                        .toNumber()
                    )
                  )}{' '}
                  to cover the rounding difference
                </Trans>
              </p>
            )}
          </div>
        </div>
      </CardContent>
    </>
  );
};

