import { toast } from 'sonner';

import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from '@/components/ui/tooltip';
import type { Receipt } from '@/models/Receipt';

import { ImageSettingsDialog } from './components/ImageSettingsDialog';
import { useImageGestures } from './hooks/useImageGestures';
import { downloadImage } from './utils/downloadImage';
import { generateImageFileName } from './utils/generateImageFileName';

interface ReceiptImageViewerProps {
  receipt: Receipt;
}

export const ReceiptImageViewer = ({ receipt }: ReceiptImageViewerProps) => {
  const { t } = useLingui();
  const { ref, style, resetImage } = useImageGestures();
  const [imageError, setImageError] = useState(false);
  const [settingsOpen, setSettingsOpen] = useState(false);
  const { userId } = useAuth();

  const imageUrl = receipt.imagePath;
  const fileName = generateImageFileName(receipt);
  const receiptId = receipt.id;
  const imageVisibility = receipt.imageVisibility;

  // Check if current user is the owner
  const isOwner =
    receipt.authUserId !== null &&
    receipt.authUserId !== undefined &&
    userId === receipt.authUserId;

  // Determine if image should be shown
  const shouldShowImage = imageVisibility !== 'owner_only' || isOwner;

  // Mount animation using react-spring
  const mountAnimation = useSpring({
    from: { opacity: 0, y: 10 },
    to: { opacity: 1, y: 0 },
    config: { duration: 300 },
  });

  const handleDownloadImage = async () => {
    if (!imageUrl) return;
    try {
      await downloadImage(imageUrl, fileName);
      toast.success(t`Image downloaded successfully`);
    } catch (error) {
      const message =
        error instanceof Error ? error.message : t`Failed to download image`;
      toast.error(t`Download failed`, {
        description: message,
      });
    }
  };

  const handleImageError = () => {
    setImageError(true);
  };

  // Reset error state when imageUrl changes, adjusting state during render
  // instead of in an effect (avoids a stale render showing the old error).
  const [prevImageUrl, setPrevImageUrl] = useState(imageUrl);
  if (imageUrl !== prevImageUrl) {
    setPrevImageUrl(imageUrl);
    setImageError(false);
  }

  return (
    <animated.div style={mountAnimation}>
      <Card className="overflow-hidden border-0 shadow-[0_2px_12px_0_rgba(0,0,0,0.06)]">
        <CardHeader className="flex flex-row items-center justify-between border-b border-border/50 pb-2">
          <CardTitle className="flex items-center gap-2 font-display text-lg font-semibold">
            <ImageIcon className="h-5 w-5 text-primary" />
            <Trans>Receipt Image</Trans>
          </CardTitle>
          <div className="flex items-center gap-2">
            {imageUrl && shouldShowImage && (
              <Button
                variant="outline"
                size="sm"
                className="h-8"
                onClick={handleDownloadImage}
              >
                <Download className="mr-1 h-4 w-4" />
                <Trans>Download</Trans>
              </Button>
            )}
            {isOwner && receiptId && (
              <TooltipProvider>
                <Tooltip>
                  <TooltipTrigger asChild>
                    <Button
                      variant="ghost"
                      size="sm"
                      className="h-8 w-8 p-0"
                      onClick={() => setSettingsOpen(true)}
                      aria-label={t`Image settings`}
                    >
                      <Settings className="h-4 w-4" aria-hidden />
                    </Button>
                  </TooltipTrigger>
                  <TooltipContent>
                    <p>
                      <Trans>Image Settings</Trans>
                    </p>
                  </TooltipContent>
                </Tooltip>
              </TooltipProvider>
            )}
          </div>
        </CardHeader>
        <CardContent className="p-0">
          {imageUrl && shouldShowImage ? (
            <div className="relative overflow-hidden bg-muted/40">
              {imageError ? (
                <div className="flex flex-col items-center justify-center px-4 py-16 text-center">
                  <svg
                    className="mb-4 h-16 w-16 text-muted-foreground/40"
                    fill="none"
                    stroke="currentColor"
                    viewBox="0 0 24 24"
                    xmlns="http://www.w3.org/2000/svg"
                    aria-hidden
                  >
                    <path
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      strokeWidth="2"
                      d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z"
                    />
                  </svg>
                  <p className="text-muted-foreground">
                    <Trans>Failed to load receipt image</Trans>
                  </p>
                </div>
              ) : (
                <animated.div
                  className="relative h-full w-full touch-none"
                  ref={ref}
                  style={style}
                >
                  <img
                    src={imageUrl}
                    alt={t`Receipt`}
                    className="mx-auto max-h-[75vh] touch-none object-contain transition-transform duration-100"
                    onError={handleImageError}
                  />
                </animated.div>
              )}
              {!imageError && (
                <div className="absolute right-3 top-3 flex gap-2">
                  <Button
                    variant="secondary"
                    size="sm"
                    className="rounded-full opacity-80 shadow-md hover:opacity-100"
                    onClick={resetImage}
                    aria-label={t`Reset image zoom`}
                  >
                    <Undo className="h-4 w-4" aria-hidden />
                  </Button>
                </div>
              )}
            </div>
          ) : imageUrl && !shouldShowImage ? (
            <div className="flex flex-col items-center justify-center bg-muted/30 px-4 py-16 text-center">
              <ImageIcon className="mb-4 h-16 w-16 text-muted-foreground/40" />
              <p className="text-muted-foreground">
                <Trans>Image hidden by owner</Trans>
              </p>
              <p className="mt-2 text-sm text-muted-foreground/70">
                <Trans>The receipt image is only visible to the owner</Trans>
              </p>
            </div>
          ) : (
            <div className="flex flex-col items-center justify-center bg-muted/30 px-4 py-16 text-center">
              <ImageIcon className="mb-4 h-16 w-16 text-muted-foreground/40" />
              <p className="text-muted-foreground">
                <Trans>Receipt image not available</Trans>
              </p>
              <p className="mt-2 text-sm text-muted-foreground/70">
                <Trans>
                  The original receipt image might not be stored or is no longer
                  accessible
                </Trans>
              </p>
            </div>
          )}
        </CardContent>
      </Card>
      {isOwner && receiptId && (
        <ImageSettingsDialog
          open={settingsOpen}
          onOpenChange={setSettingsOpen}
          receiptId={receiptId}
          imageVisibility={imageVisibility}
        />
      )}
    </animated.div>
  );
};

import { Trans, useLingui } from '@lingui/react/macro';
import Decimal from 'decimal.js';
import { Trash } from 'lucide-react';
import { useState } from 'react';

import { formatCurrency } from '@/components/Receipt/utils/format-currency';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { useReceiptMutation } from '@/features/receipt-viewer/hooks/useReceiptMutation';
import EditableDetail from '@/features/summary-card/EditableDetail';
import { cn } from '@/lib/utils';

interface GratuityEditorProps {
  receiptGratuity: Decimal;
  receiptId: number;
}

/**
 * GratuityEditor component that allows editing and saving gratuity values.
 * Performs mutations using Zero mutators.
 */
const GratuityEditor = ({
  receiptGratuity = new Decimal(0),
  receiptId,
}: GratuityEditorProps) => {
  const { t } = useLingui();
  const [gratuity, setGratuity] = useState<Decimal>(receiptGratuity);
  const [isEditing, setIsEditing] = useState(false);

  // Keep the editable draft in sync when the saved gratuity prop changes,
  // adjusting state during render instead of in an effect (avoids an extra
  // render with a stale value). See react.dev "you might not need an effect".
  const [prevReceiptGratuity, setPrevReceiptGratuity] =
    useState<Decimal>(receiptGratuity);
  if (!receiptGratuity.equals(prevReceiptGratuity)) {
    setPrevReceiptGratuity(receiptGratuity);
    setGratuity(receiptGratuity);
  }

  const resetToInitialValue = () => {
    setGratuity(receiptGratuity);
  };

  const hasValueToDelete = !receiptGratuity.isZero();

  const { mutate, isSaving } = useReceiptMutation({
    onSuccess: () => setIsEditing(false),
  });

  const handleEditGratuity = () => {
    resetToInitialValue();
    setIsEditing(true);
  };

  const handleSaveGratuity = async () => {
    await mutate({
      id: receiptId,
      gratuity: gratuity.toNumber(),
    });
  };

  const handleGratuityChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const rawValue = e.target.value;

    // Treat empty or "." as 0
    if (rawValue === '' || rawValue === '.') {
      setGratuity(new Decimal(0));
      return;
    }

    // Parse with Decimal, fallback to current value on invalid input
    let parsedValue: Decimal;
    try {
      parsedValue = new Decimal(rawValue);
    } catch {
      return; // Keep current value on invalid input
    }

    // Clamp to non-negative value
    const clampedValue = Decimal.max(0, parsedValue);

    // Round to two decimals
    const roundedValue = clampedValue.toDP(2);

    setGratuity(roundedValue);
  };

  const handleCancelGratuity = () => {
    setGratuity(receiptGratuity);
    setIsEditing(false);
  };

  const handleDeleteGratuity = async () => {
    await mutate({
      id: receiptId,
      gratuity: 0,
    });
  };

  if (!hasValueToDelete && !isEditing) {
    return (
      <div className="-ml-2 -mr-2 rounded-sm border">
        <EditableDetail
          label={t`Gratuity`}
          value={formatCurrency(0)}
          onClick={handleEditGratuity}
        />
      </div>
    );
  }

  return (
    <div className="-ml-2 -mr-2 rounded-sm border">
      {isEditing ? (
        <div className="flex flex-col gap-4 bg-background px-2 py-2">
          <div className="flex items-center justify-between gap-2">
            <Label htmlFor="gratuity" className="text-sm font-medium">
              <Trans>Gratuity:</Trans>
            </Label>
          </div>

          <div className="flex items-center gap-2">
            <span className="select-none pr-1 text-lg text-muted-foreground">
              $
            </span>
            <Input
              type="number"
              value={gratuity.toNumber()}
              onChange={handleGratuityChange}
              placeholder={t`Gratuity`}
              min={0}
              step="0.01"
              required
              className="text-center"
              id="gratuity"
              disabled={isSaving}
            />
          </div>

          <div
            className={cn(
              'flex justify-end',
              hasValueToDelete && 'justify-between'
            )}
          >
            {hasValueToDelete && (
              <Button
                variant="outline"
                size="icon"
                className="border-red-500 text-red-500"
                onClick={handleDeleteGratuity}
                aria-label={t`Delete gratuity`}
                title={t`Delete gratuity`}
                disabled={isSaving}
              >
                <Trash className="size-4" />
              </Button>
            )}
            <div className="flex gap-2">
              <Button
                onClick={handleCancelGratuity}
                variant="outline"
                disabled={isSaving}
              >
                <Trans>Cancel</Trans>
              </Button>
              <Button
                onClick={handleSaveGratuity}
                variant="outline"
                disabled={isSaving}
              >
                <Trans>Done</Trans>
              </Button>
            </div>
          </div>
        </div>
      ) : (
        <EditableDetail
          label={t`Gratuity`}
          value={formatCurrency(receiptGratuity)}
          onClick={handleEditGratuity}
        />
      )}
    </div>
  );
};

export default GratuityEditor;

