  type: 'SET_FLAG';
  value: FlagValue;
  name: keyof FeatureFlags;
}

interface SetFlagsAction {
  type: 'SET_FLAGS';
  flags: FeatureFlags;
}

interface ClearFlagsAction {
  type: 'CLEAR_FLAGS';
}

type FeatureFlagAction = SetFlagAction | SetFlagsAction | ClearFlagsAction;

